from datetime import datetime

import pytest
from isoduration import add_duration


# Basic component tests
class TestYears:
    def test_add_one_year(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y") == datetime(2026, 3, 10)

    def test_add_multiple_years(self):
        assert add_duration(datetime(2025, 3, 10), "P10Y") == datetime(2035, 3, 10)

    def test_add_zero_years(self):
        assert add_duration(datetime(2025, 3, 10), "P0Y") == datetime(2025, 3, 10)

    def test_leap_year_rollover(self):
        # Feb 29 in leap year, adding 1 year goes to non-leap year
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)


class TestMonths:
    def test_add_one_month(self):
        assert add_duration(datetime(2025, 3, 10), "P1M") == datetime(2025, 4, 10)

    def test_add_multiple_months(self):
        assert add_duration(datetime(2025, 3, 10), "P10M") == datetime(2025, 1, 10)

    def test_add_zero_months(self):
        assert add_duration(datetime(2025, 3, 10), "P0M") == datetime(2025, 3, 10)

    def test_month_overflow_day(self):
        # Jan 31 + 1 month should give Feb 28/29 (last day of Feb)
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)
        # Jan 31 + 1 month in leap year should give Feb 29
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_month_overflow_multiple(self):
        # May 31 + 2 months = July 31
        assert add_duration(datetime(2025, 5, 31), "P2M") == datetime(2025, 7, 31)
        # Aug 31 + 1 month = Sep 30 (overflow)
        assert add_duration(datetime(2025, 8, 31), "P1M") == datetime(2025, 9, 30)

    def test_multiple_months_year_boundary(self):
        # Nov 15 + 3 months = Feb 15 next year
        assert add_duration(datetime(2025, 11, 15), "P3M") == datetime(2026, 2, 15)


class TestYearsAndMonths:
    def test_years_and_months_together(self):
        # 2024-01-31 + P1M = 2024-02-29 (calendar months applied together)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)
        # 2024-02-29 + P1Y1M = 2025-03-29 (13 months in one step)
        assert add_duration(datetime(2024, 2, 29), "P1Y1M") == datetime(2025, 3, 29)

    def test_years_and_months_overflow(self):
        # 2024-01-31 + P1Y1M = 2025-02-28
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_zero_years_and_months(self):
        assert add_duration(datetime(2025, 3, 10), "P0Y0M") == datetime(2025, 3, 10)


