class TestSeconds:
    def test_add_one_second(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1S") == datetime(2025, 3, 10, 8, 0, 1)

    def test_add_multiple_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT30S") == datetime(2025, 3, 10, 8, 0, 30)

    def test_add_zero_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0S") == datetime(2025, 3, 10, 8, 0, 0)

    def test_minute_boundary(self):
