class TestCombinations:
    def test_years_months_days(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y2M3D") == datetime(2026, 5, 13)

    def test_years_months_days_time(self):
        assert add_duration(datetime(2025, 3, 10, 8), "P1Y2M3DT4H5M6S") == datetime(2026, 5, 13, 12, 5, 6)

    def test_all_components(self):
        assert add_duration(datetime(2025, 3, 10, 8, 0, 0), "P1Y2M4W5DT6H7M8S") == datetime(2026, 6, 2, 14, 7, 8)

    def test_days_and_time(self):
        assert add_duration(datetime(2025, 3, 10, 8), "P5DT3H30M") == datetime(2025, 3, 15, 11, 30)


class TestFractionalComponents:
    def test_fractional_seconds_dot(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5S")
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_seconds_comma(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1,5S")
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5M")
        assert result == datetime(2025, 3, 10, 8, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.5H")
        assert result == datetime(2025, 3, 10, 9, 30)

    def test_fractional_days(self):
        # P0.5D is 12 hours
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "P0.5D")
        assert result == datetime(2025, 3, 10, 12, 0, 0)

    def test_fractional_weeks(self):
        # P0.5W is 3.5 days = 3 days 12 hours
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "P0.5W")
        assert result == datetime(2025, 3, 13, 12, 0, 0)

    def test_fractional_zero_integer(self):
        # PT0.5S is 0.5 seconds
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.5S")
        assert result == datetime(2025, 3, 10, 8, 0, 0, 500000)

    def test_fractional_microsecond_precision(self):
        # PT0.0000005S - rounds to nearest microsecond
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.0000005S")
        # 0.0000005 seconds = 0.5 microseconds, rounds to 1 microsecond
        assert result == datetime(2025, 3, 10, 8, 0, 0, 1)

    def test_fractional_multiple_places(self):
        result = add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT1.25H")
        assert result == datetime(2025, 3, 10, 1, 15, 0)


class TestNegativeDurations:
    def test_negative_sign(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    def test_negative_months(self):
        assert add_duration(datetime(2025, 3, 10), "-P1M") == datetime(2025, 2, 10)

    def test_negative_years(self):
        assert add_duration(datetime(2025, 3, 10), "-P1Y") == datetime(2024, 3, 10)

    def test_negative_time(self):
        assert add_duration(datetime(2025, 3, 10, 8, 30), "-PT1H30M") == datetime(2025, 3, 10, 7)

    def test_negative_months_with_overflow(self):
        # 2024-03-31 minus P1M = 2024-02-29 (back one month to 2024-02-xx, day 31 doesn't exist, use last day)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_months_and_days_order(self):
        # 2024-03-01 minus P1M1D = 2024-01-31 (first back one month to 2024-02-01, then back one day)
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_positive_sign(self):
        assert add_duration(datetime(2025, 3, 10), "+P1D") == datetime(2025, 3, 11)

    def test_negative_fractional(self):
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "-PT1.5S")
        assert result == datetime(2025, 3, 10, 7, 59, 58, 500000)


class TestSyntaxValidation:
    # Required elements
    def test_missing_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "1D")

    def test_only_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P")

    def test_only_pt(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT")

    def test_pt_without_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT")

    # Order validation
    def test_wrong_order_md_reversed(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D1M")

    def test_wrong_order_dt_reversed(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1T1D")

    def test_component_before_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "1YP")

    def test_component_after_all(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D1")

    # Weeks cannot combine
    def test_weeks_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P2W3D")

    def test_weeks_with_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2W")

    def test_weeks_with_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1Y2W")

    def test_weeks_with_time(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P2WT1H")

    # Duplicate components
    def test_duplicate_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1D2D")

    def test_duplicate_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2M")

    def test_duplicate_time_components(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1H2H")

    # Whitespace
    def test_whitespace_in_duration(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P 1D")

    def test_whitespace_between_number_and_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1 D")

    # Invalid characters
    def test_invalid_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1X")

    def test_non_numeric_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PaD")

    # M ambiguity (months vs minutes)
    def test_m_before_t_is_months(self):
        # P1M should be 1 month, not 1 minute
        result = add_duration(datetime(2025, 1, 31), "P1M")
        assert result == datetime(2025, 2, 28)

    def test_m_after_t_is_minutes(self):
        # PT1M should be 1 minute, not 1 month
        result = add_duration(datetime(2025, 3, 10, 8, 0), "PT1M")
        assert result == datetime(2025, 3, 10, 8, 1)

    # Sign validation
    def test_sign_on_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P-1D")

    def test_sign_on_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1DT-1H")

    def test_double_sign(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "--P1D")

    def test_sign_between_p_and_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P-1D")

    # Fractional component constraints
    def test_fractional_on_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5Y")

    def test_fractional_on_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5M")

    def test_fractional_not_on_last(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1.5D2D")

    def test_fractional_on_middle_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.5H2M")

    def test_no_digits_before_decimal(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT.5S")

    def test_no_digits_after_decimal(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.S")

    # Both decimal separators not allowed
    def test_multiple_decimal_points(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.5.2S")

    def test_dot_and_comma_mix(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "PT1.5,2S")


class TestDatetimeRangeErrors:
    def test_overflow_year_max(self):
        # Try to add years that exceed datetime.max (year 9999)
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 1, 1), "P1Y")

    def test_overflow_month_exceeds_max(self):
        # Try to add months that exceed datetime.max
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1M")

    def test_underflow_year_min(self):
        # Try to subtract years below datetime.min (year 1)
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1Y")

    def test_underflow_month_below_min(self):
        # Try to subtract months below datetime.min
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1M")


class TestEdgeCases:
    def test_leap_day_operations(self):
        # 2024 is a leap year
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_leap_year_february(self):
        # Non-leap year February has 28 days
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_december_to_january(self):
        assert add_duration(datetime(2025, 12, 15), "P1M") == datetime(2026, 1, 15)

    def test_very_large_duration(self):
        # Large but valid duration
        result = add_duration(datetime(2025, 1, 1), "P100Y")
        assert result == datetime(2125, 1, 1)

    def test_midnight_boundary(self):
        result = add_duration(datetime(2025, 3, 10, 23, 59, 59), "PT1S")
        assert result == datetime(2025, 3, 11, 0, 0, 0)

    def test_very_small_fractional(self):
        # Very small fractional second
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT0.000001S")
        assert result == datetime(2025, 3, 10, 8, 0, 0, 1)

    def test_zero_duration(self):
        dt = datetime(2025, 3, 10, 8, 30, 45)
        result = add_duration(dt, "P0Y0M0W0DT0H0M0S")
        assert result == dt

    def test_fractional_second_rounding(self):
        # Test rounding of fractional seconds to nearest microsecond
        result = add_duration(datetime(2025, 3, 10, 8, 0, 0), "PT1.9999995S")
        # 1.9999995 seconds rounds to 2 seconds
        assert result == datetime(2025, 3, 10, 8, 0, 2)

    def test_large_leading_zeros(self):
        # Leading zeros should be accepted
        assert add_duration(datetime(2025, 3, 10), "P00001D") == datetime(2025, 3, 11)

    def test_months_to_next_year(self):
        # Wrapping across year boundaries
        result = add_duration(datetime(2025, 11, 30), "P4M")
        assert result == datetime(2026, 3, 30)
